import numpy as np
from scipy import ndimage
from PIL import Image
from scipy.sparse import csr_matrix
from scipy.sparse.csgraph import minimum_spanning_tree

def thin(im):
 im=im.astype(bool).copy()
 for it in range(500):
  changed=False
  for phase in [0,1]:
   a=np.pad(im,1)
   p=[a[:-2,1:-1],a[:-2,2:],a[1:-1,2:],a[2:,2:],a[2:,1:-1],a[2:,:-2],a[1:-1,:-2],a[:-2,:-2]]
   count=sum(x.astype(int) for x in p);trans=sum((~p[i]&p[(i+1)%8]).astype(int) for i in range(8))
   if phase==0:rem=(~(p[0]&p[2]&p[4]))&(~(p[2]&p[4]&p[6]))
   else:rem=(~(p[0]&p[2]&p[6]))&(~(p[0]&p[4]&p[6]))
   rem&=im&(count>=2)&(count<=6)&(trans==1)
   if rem.any():im[rem]=False;changed=True
  if not changed:break
 return im

# Plan each disconnected character, with a continuous spanning walk.
def walk_pixels(im):
 ys,xs=np.where(im);pts=np.column_stack([xs,ys]);d={tuple(p):i for i,p in enumerate(pts)}
 rows=[];cols=[];vals=[]
 for i,(x,y) in enumerate(pts):
  for dx,dy in [(1,0),(0,1),(1,1),(-1,1)]:
   j=d.get((x+dx,y+dy))
   if j is not None:
    rows.extend([i,j]);cols.extend([j,i]);vals.extend([np.hypot(dx,dy)]*2)
 tree=minimum_spanning_tree(csr_matrix((vals,(rows,cols)),shape=(len(pts),len(pts))))
 a=tree+tree.T;adj=[a.getrow(i).indices.tolist() for i in range(len(pts))]
 start=np.lexsort((xs,ys))[0]
 visited=set();seq=[]
 def dfs(i,parent=-1):
  visited.add(i);seq.append(i)
  for j in adj[i]:
   if j!=parent:dfs(j,i);seq.append(i)
 import sys;sys.setrecursionlimit(20000)
 dfs(start)
 return pts[seq].astype(float),len(visited),len(pts)

if __name__=='__main__':
 from analyze import kernel
 mask=np.load('/app/output/mask.npy')
 # Skeleton of the valid broad-nib centres.
 k=kernel(-30)
 er=ndimage.binary_erosion(mask,k);sk=thin(er)
 lab,n=ndimage.label(sk,np.ones((3,3)))
 paths=[];render=np.zeros(mask.shape,bool)
 for i in range(1,n+1):
  part=lab==i
  if part.sum()<6:continue
  path,v,N=walk_pixels(part);paths.append(path)
  render|=ndimage.binary_dilation(part,k)
  print('path',len(paths)-1,len(path),path.min(0),path.max(0),v,N)
 print('skeleton coverage',np.sum(render&mask)/mask.sum(),'iou',np.sum(render&mask)/np.sum(render|mask))
 I=np.ones((*mask.shape,3),np.uint8)*245;I[mask>0]=[190,50,50];I[render]=[20,20,20];I[sk]=[30,150,240]
 Image.fromarray(I[440:580,230:780]).resize((1100,280)).save('/app/output/skeleton.png')
 np.savez('/app/output/paths.npz',**{str(i):p for i,p in enumerate(paths)})
